import hashlib, json

def digest(operation):
    blob = json.dumps(operation, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(blob.encode()).hexdigest()

class Guard:
    def __init__(self):
        self.done = {}
    def execute(self, op, approval, now):
        if op["tenant"] != approval["tenant"] or now >= approval["expires"]:
            raise PermissionError("scope or expiration")
        if op["action"] != "invite" or digest(op) != approval["operation_hash"]:
            raise PermissionError("unapproved operation")
        request_id = op["request_id"]
        if request_id in self.done:
            old_hash, result = self.done[request_id]
            if old_hash != digest(op):
                raise ValueError("request id reused with changed args")
            return result
        result = f"sent:{op['vendor']}:{op['requisition']}"
        self.done[request_id] = (digest(op), result)
        return result

op = dict(tenant="T1", request_id="r7", action="invite", vendor="V17", requisition="R20")
a = dict(tenant="T1", expires=100, operation_hash=digest(op))
g = Guard()
assert g.execute(op, a, 50) == "sent:V17:R20"
assert g.execute(op, a, 50) == "sent:V17:R20"
for changed in [dict(op, requisition="R21"), dict(op, tenant="T2")]:
    try:
        g.execute(changed, a, 50)
        raise AssertionError("modified operation executed")
    except PermissionError:
        pass
try:
    g.execute(op, a, 100)
    raise AssertionError("expired approval accepted")
except PermissionError:
    pass
print("all authorization and replay assertions passed")

def run_plan(steps, execute, verify):
    pending = {s["id"]: s for s in steps}
    if len(pending) != len(steps):
        raise ValueError("duplicate id")
    if any(d not in pending for s in steps for d in s["deps"]):
        raise ValueError("missing dependency")
    passed, trace = set(), []
    while pending:
        ready = [s for s in pending.values() if set(s["deps"]) <= passed]
        if not ready:
            raise ValueError("cycle or blocked dependency")
        step = ready[0]
        observation = execute(step)
        if not verify(step, observation):
            return {"status": "BLOCKED", "trace": trace, "failed": step["id"]}
        trace.append((step["id"], observation))
        passed.add(step["id"])
        del pending[step["id"]]
    return {"status": "SUCCEEDED", "trace": trace}

steps = [dict(id="build", deps=[]), dict(id="deploy", deps=["build"]), dict(id="check", deps=["deploy"])]
execute = lambda s: {"artifact": s["id"], "observed": True}
verify = lambda s, o: o["observed"] and o["artifact"] == s["id"]
assert run_plan(steps, execute, verify)["status"] == "SUCCEEDED"
assert run_plan(steps, execute, lambda s, o: s["id"] != "deploy")["failed"] == "deploy"
try:
    run_plan([dict(id="a", deps=["b"]), dict(id="b", deps=["a"])], execute, verify)
    raise AssertionError("cycle accepted")
except ValueError:
    pass
print("plan verified; bad evidence and cycle rejected")
